import React from "react";
import { useNavigate } from "react-router-dom";
import "../../styles/layout.css";
import "./DestinationsPage.css";
import { STATIC_ASSETS } from "../../utils/cloudinary";
import WorldMap from "./components/WorldMap";
import blogs from "../../data/blogs";
import { serializeLocation } from "./DestinationPage.utils";

const background = STATIC_ASSETS.destinationsPageBg;

const DestinationsPage = () => {
  const navigate = useNavigate();

  // Helper function to check if country is US
  const isUSCountry = (countryCode) => {
    return countryCode === "US";
  };

  // Create unique locations (countries and US states)
  const uniqueLocations = Object.values(
    blogs.reduce((accumulator, blog) => {
      let locationKey, displayName, path;

      if (blog.state && isUSCountry(blog.country_code)) {
        // For US states, use the state as the key
        locationKey = `USA-${blog.state}`;
        displayName = `${blog.state}, USA`;
        path = `/blog/united-states-${serializeLocation(blog.state)}`;
      } else {
        locationKey = blog.country;
        displayName = blog.country;
        path = `/blog/${serializeLocation(blog.country)}`;
      }

      // If this location doesn't exist yet, create it
      if (!accumulator[locationKey]) {
        accumulator[locationKey] = {
          displayName,
          path,
          blogs: [], // Add an array to store all blogs for this location
        };
      }

      // Add this blog to the location's blogs array
      accumulator[locationKey].blogs.push(blog);

      return accumulator;
    }, {}),
  );

  return (
    <div className="page-container">
      <div
        className="fixed-background-container"
        style={{
          backgroundImage: `url(${background})`,
        }}
      >
        <div className="fixed-background-text-container">
          <div className="fixed-background-title fixed-background-no-margin">
            Choose your destinations
          </div>
        </div>
      </div>

      <div className="container">
        <div className="dropdown-container">
          <select
            className="destination-dropdown"
            onChange={(e) => {
              if (e.target.value) {
                navigate(e.target.value);
              }
            }}
          >
            <option value="">Destinations</option>
            {uniqueLocations.map((location, index) => (
              <option key={index} value={location.path}>
                {location.displayName}
              </option>
            ))}
          </select>
        </div>
        <div className="page-content">
          <WorldMap />
        </div>
      </div>
    </div>
  );
};

export default DestinationsPage;
